Q: How to place the search bar above a List instead of in the toolbar? A: <p>Using a <code>TextField</code> instead as suggested by Joakim does what I am looking for:</p>
<pre><code>import SwiftUI

struct ContentView: View {
    @State private var inspectorShown = true

    var body: some View {
        Text(&quot;Main View&quot;)
            .inspector(isPresented: $inspectorShown) {
                InspectorView()
            }
    }
}

struct InspectorView: View {
    @State private var searchText: String = &quot;&quot;

    var body: some View {
        VStack {
            TextField(
                &quot;Search&quot;,
                text: $searchText,
                prompt: Text(&quot;\(Image(systemName: &quot;magnifyingglass&quot;)) Search&quot;)
            )
            .padding(.horizontal, 10)
            List {
                Text(&quot;One&quot;)
                Text(&quot;Two&quot;)
                Text(&quot;Three&quot;)
            }
            .listStyle(.sidebar)
        }
    }
}
</code></pre>
